package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchRequest struct {
	Query    string   `json:"query"`
	Fields   []string `json:"fields"`
	OrderBy  string   `json:"order_by"`
	Limit    int      `json:"limit"`
}

type Product struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Price float64 `json:"price"`
	SKU   string `json:"sku"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

var allowedFields = map[string]bool{
	"name": true, "price": true, "sku": true, "category": true,
	"description": true, "created_at": true,
}

var allowedOrderFields = map[string]bool{
	"name": true, "price": true, "created_at": true, "id": true,
}

func sanitizeIdentifier(s string) string {
	// Remove obvious dangerous characters
	s = strings.ReplaceAll(s, ";", "")
	s = strings.ReplaceAll(s, "--", "")
	s = strings.ReplaceAll(s, "/*", "")
	s = strings.ReplaceAll(s, "*/", "")
	return s
}

func searchProducts(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid JSON", 400)
		return
	}

	if req.Limit <= 0 || req.Limit > 100 {
		req.Limit = 20
	}

	// Build SELECT fields
	selectFields := []string{"id"}
	for _, f := range req.Fields {
		f = strings.ToLower(strings.TrimSpace(f))
		if allowedFields[f] {
			selectFields = append(selectFields, f)
		}
	}

	// Build ORDER BY - uses sanitizeIdentifier but NOT allowlist check
	orderClause := "id ASC"
	if req.OrderBy != "" {
		parts := strings.SplitN(req.OrderBy, " ", 2)
		field := sanitizeIdentifier(parts[0])
		direction := "ASC"
		if len(parts) > 1 && strings.ToUpper(parts[1]) == "DESC" {
			direction = "DESC"
		}
		// NOTE: allowedOrderFields check was intended here but field
		// is used directly after sanitization only
		orderClause = fmt.Sprintf("%s %s", field, direction)
	}

	// Parameterized query for the WHERE clause (safe)
	query := fmt.Sprintf(
		"SELECT %s FROM products WHERE name ILIKE $1 OR description ILIKE $1 ORDER BY %s LIMIT %d",
		strings.Join(selectFields, ", "),
		orderClause,
		req.Limit,
	)

	searchTerm := "%" + req.Query + "%"
	rows, err := db.Query(query, searchTerm)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var results []map[string]interface{}
	cols, _ := rows.Columns()
	for rows.Next() {
		values := make([]interface{}, len(cols))
		ptrs := make([]interface{}, len(cols))
		for i := range values {
			ptrs[i] = &values[i]
		}
		rows.Scan(ptrs...)
		row := make(map[string]interface{})
		for i, col := range cols {
			row[col] = values[i]
		}
		results = append(results, row)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/health", healthCheck)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
